package dev.krit.firsample.proto

import okio.ByteString

// UserRecord is generated by Wire from user.proto.
fun userRecord(id: String, name: String, visits: Int = 0): UserRecord =
    UserRecord(id = id, name = name, visits = visits)

fun UserRecord.toBytes(): ByteString = UserRecord.ADAPTER.encodeByteString(this)

fun decodeUserRecord(bytes: ByteString): UserRecord = UserRecord.ADAPTER.decode(bytes)
